  test("clone sheet scenario 1", { tag: '@functionality' }, async ({ browser }) => {

== V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet. A row is created the first time its id
-- is loaded, so a sheet that was never loaded before starts empty.
CREATE TABLE sheet (
    id         VARCHAR(200) PRIMARY KEY,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
== V2__sheet_today.sql
-- The sheet's own "today": every date decision and default date in the app uses it, never the real
-- clock. A sheet starts on the real date of the day it was first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- The people on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on its sheet, ignoring case and surrounding spaces (names are stored
-- trimmed; the app refuses a duplicate with a message, this index is the backstop).
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name)));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount (two decimals, 0.00 or more), a date and a note (may be empty).
-- Listed newest first (by id, descending).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, person_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent with two decimals (0.00 to 100.00). A grade without
-- a row has no rate, so its claims' due shows n/a.
CREATE TABLE rate (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL,
    rate     DECIMAL(5, 2) NOT NULL CHECK (rate >= 0 AND rate <= 100),
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT';
== V8__claim_number.sql
-- A claim's number: given when it is opened, the sheet's next one (1, 2, ...), never reused.
-- A draft has none, and voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- A claim's due fixed when it is settled: its amount times its person's grade's rate at that
-- moment, rounded half up to two decimals. Null while it is not settled, or when the grade had no
-- rate then (its due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
== V10__rate_from.sql
-- A rate can carry a from-date: a grade may have several rates, and a claim uses the one whose
-- from-date is the latest on or before the claim's date. A rate without one (null) applies from
-- the beginning of time. A grade has at most one rate per from-date (null included); setting it
-- again replaces it.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate DROP PRIMARY KEY;
== V11__claim_opened_by.sql
-- The signed-in user who opened a claim; null while it was never opened. That user cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(200);
== V12__person_version.sql
-- How many times a person has been saved; an edit names the version it loaded and is refused when
-- someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V13__statement.sql
-- A person's statements: each records the person's due-total when it was taken (null when it was
-- n/a) and the sheet's today then. The latest (highest id) is the person's last statement.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(14, 2),
    taken_on  DATE           NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement: it shows and totals stated_due (null: n/a) instead
-- of its live figure, until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
== V14__period.sql
-- The sheet's periods: a name, unique on the sheet ignoring case and surrounding spaces (the app
-- refuses a duplicate with a message, the index is the backstop), and a from and to date, both
-- inclusive. No two periods on a sheet overlap; a claim belongs to the period containing its date.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name))),
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
== V15__period_closed.sql
-- A period can be closed. Closing fixes its due-total at that moment (later rate changes do not
-- alter it); no claim dated inside a closed period can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
== V16__person_retired.sql
-- A person can be retired from a date. A person with a retirement date set counts as retired at once,
-- whatever the date; no claim dated after it can be added (or edited to such a date).
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no live total;
-- their SETTLED claims still do.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V18__role_and_setting.sql
-- Each sheet assigns a role to a user name: clerk or steward. A name without a row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);

-- Each sheet's settings, by key. A null value is blank (for clerk-limit: no limit). A key without a row is blank.
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(50)  NOT NULL,
    setting_value VARCHAR(200),
    PRIMARY KEY (sheet_id, setting_key)
);
== V19__person_patron.sql
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id)
);
== V20__person_grade.sql
-- A person's grade is dated: each grade they are given applies from its from-date, the first one
-- (null) from the beginning of time. On a date, the grade in force is the one with the latest
-- from-date on or before it. A person has at most one grade per from-date; giving one again on the
-- same date replaces it.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL,
    from_date DATE
);
CREATE INDEX person_grade_person ON person_grade (person_id, from_date);
INSERT INTO person_grade (person_id, grade, from_date) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
== V21__claim_correction.sql
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the same
-- person that it corrects (null for any other claim). The amount may now be below 0.00, so the
-- column is rebuilt without its old CHECK (amount >= 0).
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(14, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim ALTER COLUMN signed_amount SET NOT NULL;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ADD COLUMN corrects INT;
== V22__period_numbering.sql
-- A claim's number is now text: a sheet-wide number (1, 2, ...) or, while the sheet numbers by period, a number
-- within its period (<period name>-<n>, or X-<n> for a claim in no period). A correction names its claim the same way.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);

-- Each sheet's per-period sequences, by key (a period's id, or X for claims in no period): the last number given.
CREATE TABLE claim_sequence (
    sheet_id    VARCHAR(200) NOT NULL REFERENCES sheet (id),
    seq_key     VARCHAR(50)  NOT NULL,
    last_number INT          NOT NULL DEFAULT 0,
    PRIMARY KEY (sheet_id, seq_key)
);
== V23__claim_listed.sql
-- Where a claim is listed: claims are listed newest first by this key, not by id, so a claim moved to
-- another person is listed as that person's newest. A claim takes the sheet's next key when it is
-- added or moved; the sheet keeps the last key it gave.
ALTER TABLE sheet ADD COLUMN last_claim_listed BIGINT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
UPDATE sheet SET last_claim_listed = COALESCE((SELECT MAX(c.id) FROM claim c WHERE c.sheet_id = sheet.id), 0);
CREATE INDEX claim_listed ON claim (sheet_id, person_id, listed);
== V24__claim_due_by.sql
-- A claim's due-by is fixed when it is added: its date plus the terms of its person's grade in force on that date
-- (the grade's own terms, setting terms-<grade>, else the sheet's terms). Later changes to the terms or to the claim's
-- date leave it as it is. Existing claims take their date plus the sheet's terms (14 until they are set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.setting_value AS INT) FROM sheet_setting s
    WHERE s.sheet_id = claim.sheet_id AND s.setting_key = 'terms'), 14), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V25__claim_log.sql
-- A claim's status log: one line per status it has had, in the order it had them (by id) — who made the change, the
-- sheet's today then, and the claim's due as computed at that moment (null: n/a). Its DRAFT line is written when it is added.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(10)    NOT NULL,
    by_user   VARCHAR(200)   NOT NULL,
    logged_on DATE           NOT NULL,
    due       DECIMAL(14, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
== V26__person_hold.sql
-- A person may have several holds over time, each from its from-date to its to-date (null: open-ended), both
-- inclusive. A hold leaves out of the live totals only the person's OPEN and PENDING claims dated within it that no
-- statement binds. A person held before keeps a hold from the beginning of time (null from-date).
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id, id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V27__rate_to.sql
-- A rate can carry a to-date: it applies through that date (null: with no end). A claim dated after
-- the to-date of the rate that would apply to it, with no later rate in force then, has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V28__period_person_total.sql
-- Closing a period also fixes each person's due-total for it, for every person on the sheet at that moment
-- (a person added later has none: 0.00). The period's closed_total is the sum of these. Reopening removes them.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V29__setting_from.sql
-- The settings that carry a figure (the floor, the late percent, the terms and each grade's, the clerk limit, the cap)
-- are dated: each value is in force from its from-date until the next one's. A null value is blank. A value already
-- set before settings were dated is kept as in force from the beginning of time.
CREATE TABLE sheet_setting_from (
    sheet_id      VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(50)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);

INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)
SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');

DELETE FROM sheet_setting WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
== V30__claim_deferred.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches that date it counts
-- in no total, is not overdue, cannot be settled and is left unbound by a statement (null: never deferred).
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V31__claim_proofs.sql
-- How many proofs a claim carries: raised by one at a time while it is neither SETTLED nor VOID. A claim whose due is
-- above the proof threshold in force on its date cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT DEFAULT 0 NOT NULL;
== V32__role_viewer.sql
-- A third role, viewer: sees every screen and figure and may change nothing. The role's check is
-- unnamed (generated), so the table is rebuilt with the wider check.
CREATE TABLE sheet_role_new (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_new (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
== V33__claim_split_from.sql
-- The number of the claim an OPEN claim was split off (null: not split off one). The claim split keeps the rest of its
-- amount and shows nothing.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(50);
== V34__person_watch.sql
-- The users watching each person, in the order they started watching (id order). A user watches a person at most once.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
== V35__delegation.sql
-- A steward's delegation of the steward role to a user name, for a from-date to a to-date (inclusive) by the sheet's
-- today. While the sheet's today is inside the range the user acts as a steward, for the steward who delegated.
CREATE TABLE sheet_delegation (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    by_user   VARCHAR(200) NOT NULL
);
CREATE INDEX sheet_delegation_user ON sheet_delegation (sheet_id, user_name);
== V36__sheet_archived.sql
-- An archived sheet: everything on it stays visible, and every change to it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V37__person_terms.sql
-- A person's own terms: a whole number of days, null for none. A claim added for the person is due by
-- its date plus these terms, else their grade's, else the sheet's.
ALTER TABLE person ADD COLUMN terms INT;
== V38__claim_lock.sql
-- A claim's editor lock: the signed-in user whose open editor holds the claim. Others cannot open its
-- editor or save it until the holder saves or cancels, or the sheet's today changes (every lock is dropped).
CREATE TABLE claim_lock (
    claim_id  BIGINT       PRIMARY KEY REFERENCES claim (id),
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    locked_by VARCHAR(200) NOT NULL
);
CREATE INDEX claim_lock_sheet ON claim_lock (sheet_id);
== V39__period_soft_close.sql
-- A period can be soft-closed: its due-total (closed_total) and each person's (period_person_total) are fixed as
-- closing fixes them, but claims dated inside it can still be added, edited, opened, settled and voided. A
-- soft-closed period is not closed; closing it fixes the figures afresh, reopening removes them.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period containing its date was soft-closed is a late entry, for good.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V40__sheet_snapshot.sql
-- A sheet as it stood at the end of a run of its todays: taken as the sheet's today moves on from `through` to
-- `until`, it holds every change made while the sheet's today was `through` or earlier, and none made later. A
-- statement as of a date reads the latest snapshot with through <= date < until (see SheetHistory).
CREATE TABLE sheet_snapshot (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    through  DATE         NOT NULL,
    until    DATE         NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, id);

-- The snapshotted rows: each table a statement's figures read, with the snapshot's id last.
CREATE SCHEMA hist;
CREATE TABLE hist.sheet AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet t WHERE FALSE;
CREATE TABLE hist.person AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person t WHERE FALSE;
CREATE TABLE hist.person_grade AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_grade t WHERE FALSE;
CREATE TABLE hist.person_hold AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_hold t WHERE FALSE;
CREATE TABLE hist.person_patron AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_patron t WHERE FALSE;
CREATE TABLE hist.statement AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM statement t WHERE FALSE;
CREATE TABLE hist.claim AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim t WHERE FALSE;
CREATE TABLE hist.rate AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM rate t WHERE FALSE;
CREATE TABLE hist.sheet_setting AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_setting t WHERE FALSE;
CREATE TABLE hist.sheet_setting_from AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_setting_from t WHERE FALSE;
CREATE INDEX hist_sheet_snapshot ON hist.sheet (snapshot_id);
CREATE INDEX hist_person_snapshot ON hist.person (snapshot_id);
CREATE INDEX hist_person_grade_snapshot ON hist.person_grade (snapshot_id);
CREATE INDEX hist_person_hold_snapshot ON hist.person_hold (snapshot_id);
CREATE INDEX hist_person_patron_snapshot ON hist.person_patron (snapshot_id);
CREATE INDEX hist_statement_snapshot ON hist.statement (snapshot_id);
CREATE INDEX hist_claim_snapshot ON hist.claim (snapshot_id);
CREATE INDEX hist_rate_snapshot ON hist.rate (snapshot_id);
CREATE INDEX hist_sheet_setting_snapshot ON hist.sheet_setting (snapshot_id);
CREATE INDEX hist_sheet_setting_from_snapshot ON hist.sheet_setting_from (snapshot_id);

-- A snapshot laid out as the live tables, for the length of one request: the repositories read it unchanged with
-- this schema current, the sheet's today standing at the statement's date. Emptied again before the request ends.
CREATE SCHEMA asof;
CREATE TABLE asof.sheet AS SELECT * FROM sheet WHERE FALSE;
CREATE TABLE asof.person AS SELECT * FROM person WHERE FALSE;
CREATE TABLE asof.person_grade AS SELECT * FROM person_grade WHERE FALSE;
CREATE TABLE asof.person_hold AS SELECT * FROM person_hold WHERE FALSE;
CREATE TABLE asof.person_patron AS SELECT * FROM person_patron WHERE FALSE;
CREATE TABLE asof.statement AS SELECT * FROM statement WHERE FALSE;
CREATE TABLE asof.claim AS SELECT * FROM claim WHERE FALSE;
CREATE TABLE asof.rate AS SELECT * FROM rate WHERE FALSE;
CREATE TABLE asof.sheet_setting AS SELECT * FROM sheet_setting WHERE FALSE;
CREATE TABLE asof.sheet_setting_from AS SELECT * FROM sheet_setting_from WHERE FALSE;
== V41__sheet_snapshot_whole.sql
-- The as-of view: the whole screen is shown as the sheet stood at the end of a date, so a snapshot (see V40) holds
-- every table the screen reads, not only those a statement's figures read.
CREATE TABLE hist.person_watch AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_watch t WHERE FALSE;
CREATE TABLE hist.claim_log AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_log t WHERE FALSE;
CREATE TABLE hist.claim_lock AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_lock t WHERE FALSE;
CREATE TABLE hist.period AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM period t WHERE FALSE;
CREATE TABLE hist.period_person_total AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM period_person_total t WHERE FALSE;
CREATE TABLE hist.sheet_role AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_role t WHERE FALSE;
CREATE TABLE hist.sheet_delegation AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_delegation t WHERE FALSE;
CREATE INDEX hist_person_watch_snapshot ON hist.person_watch (snapshot_id);
CREATE INDEX hist_claim_log_snapshot ON hist.claim_log (snapshot_id);
CREATE INDEX hist_claim_lock_snapshot ON hist.claim_lock (snapshot_id);
CREATE INDEX hist_period_snapshot ON hist.period (snapshot_id);
CREATE INDEX hist_period_person_total_snapshot ON hist.period_person_total (snapshot_id);
CREATE INDEX hist_sheet_role_snapshot ON hist.sheet_role (snapshot_id);
CREATE INDEX hist_sheet_delegation_snapshot ON hist.sheet_delegation (snapshot_id);

CREATE TABLE asof.person_watch AS SELECT * FROM person_watch WHERE FALSE;
CREATE TABLE asof.claim_log AS SELECT * FROM claim_log WHERE FALSE;
CREATE TABLE asof.claim_lock AS SELECT * FROM claim_lock WHERE FALSE;
CREATE TABLE asof.period AS SELECT * FROM period WHERE FALSE;
CREATE TABLE asof.period_person_total AS SELECT * FROM period_person_total WHERE FALSE;
CREATE TABLE asof.sheet_role AS SELECT * FROM sheet_role WHERE FALSE;
CREATE TABLE asof.sheet_delegation AS SELECT * FROM sheet_delegation WHERE FALSE;
== V42__claim_reminded.sql
-- An OPEN or PENDING claim can be reminded once per sheet-today: the last day a reminder was written (null: never).
ALTER TABLE claim ADD COLUMN reminded_on DATE;
ALTER TABLE hist.claim ADD COLUMN reminded_on DATE;
ALTER TABLE asof.claim ADD COLUMN reminded_on DATE;
== V43__holiday.sql
-- The sheet's holidays: each date at most once on a sheet (the app refuses a duplicate with a message, the index is
-- the backstop). A claim's due-by, fixed when it is added, is moved past the holidays on the sheet then.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(200) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.holiday AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM holiday t WHERE FALSE;
CREATE INDEX hist_holiday_snapshot ON hist.holiday (snapshot_id);
CREATE TABLE asof.holiday AS SELECT * FROM holiday WHERE FALSE;
== V44__claim_business_day_terms.sql
-- A claim's due-by now counts business days: it is the terms-th day after the date it counts from that is not a
-- Saturday, a Sunday or a holiday on the sheet, worked out whenever the claim is read (so a holiday added later moves
-- it). Each claim keeps the date its due-by counts from (its date when it was added: a later change to the date leaves
-- it) and the terms it was fixed with (those in force on that date for its person). Existing claims count from their
-- date, with the days their fixed due-by lay after it as their terms.
ALTER TABLE claim ADD COLUMN due_from DATE;
ALTER TABLE claim ADD COLUMN terms INT;
UPDATE claim SET due_from = claim_date, terms = GREATEST(DATEDIFF(DAY, claim_date, due_by), 0);
ALTER TABLE claim ALTER COLUMN due_from SET NOT NULL;
ALTER TABLE claim ALTER COLUMN terms SET NOT NULL;
ALTER TABLE claim DROP COLUMN due_by;

-- Snapshotted with the rest of the screen (see V40, V41).
ALTER TABLE hist.claim ADD COLUMN due_from DATE;
ALTER TABLE hist.claim ADD COLUMN terms INT;
UPDATE hist.claim SET due_from = claim_date, terms = GREATEST(DATEDIFF(DAY, claim_date, due_by), 0);
ALTER TABLE hist.claim DROP COLUMN due_by;
ALTER TABLE asof.claim ADD COLUMN due_from DATE;
ALTER TABLE asof.claim ADD COLUMN terms INT;
ALTER TABLE asof.claim DROP COLUMN due_by;
== V45__claim_ref.sql
-- A claim may carry an external reference (null: none), used at most once on a sheet, comparing without regard to case.
ALTER TABLE claim ADD COLUMN ref VARCHAR(200);
ALTER TABLE hist.claim ADD COLUMN ref VARCHAR(200);
ALTER TABLE asof.claim ADD COLUMN ref VARCHAR(200);
== V46__claim_tags.sql
-- A claim may carry tags (null: none): trimmed, lower-cased, without repeats, sorted and joined by commas.
ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
ALTER TABLE hist.claim ADD COLUMN tags VARCHAR(1000);
ALTER TABLE asof.claim ADD COLUMN tags VARCHAR(1000);

-- Every tag ever used on a sheet's claims, kept when no claim carries it any more.
CREATE TABLE claim_tag (
    sheet_id VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    tag      VARCHAR(1000) NOT NULL,
    PRIMARY KEY (sheet_id, tag)
);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.claim_tag AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_tag t WHERE FALSE;
CREATE INDEX hist_claim_tag_snapshot ON hist.claim_tag (snapshot_id);
CREATE TABLE asof.claim_tag AS SELECT * FROM claim_tag WHERE FALSE;
== V47__void_reason.sql
-- The sheet's void reasons, in the order added: each trimmed reason at most once on a sheet (the app refuses a repeat
-- with a message, the index is the backstop). While a sheet has any, a void needs one of them.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(1000) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);

-- The reason a claim was voided with (null: none given).
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(1000);
ALTER TABLE hist.claim ADD COLUMN void_reason VARCHAR(1000);
ALTER TABLE asof.claim ADD COLUMN void_reason VARCHAR(1000);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.void_reason AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM void_reason t WHERE FALSE;
CREATE INDEX hist_void_reason_snapshot ON hist.void_reason (snapshot_id);
CREATE TABLE asof.void_reason AS SELECT * FROM void_reason WHERE FALSE;
== V48__claim_comment.sql
-- A claim's comments, in the order written (by id): who wrote it, the sheet's today then, and its trimmed text.
CREATE TABLE claim_comment (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    claim_id   BIGINT        NOT NULL REFERENCES claim (id),
    by_user    VARCHAR(200)  NOT NULL,
    written_on DATE          NOT NULL,
    text       VARCHAR(4000) NOT NULL
);
CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, claim_id, id);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.claim_comment AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_comment t WHERE FALSE;
CREATE INDEX hist_claim_comment_snapshot ON hist.claim_comment (snapshot_id);
CREATE TABLE asof.claim_comment AS SELECT * FROM claim_comment WHERE FALSE;
== V49__claim_edited_by.sql
-- The user who last edited the claim through its form or amount entry (null: never edited); like its opener, they may not settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(200);
ALTER TABLE hist.claim ADD COLUMN edited_by VARCHAR(200);
ALTER TABLE asof.claim ADD COLUMN edited_by VARCHAR(200);
== V50__claim_due_by_fixed.sql
-- A claim's due-by is fixed again when it is added (counted over the sheet's holidays as they stand then), and is
-- re-fixed only when a holiday is added on or before it while the claim is neither SETTLED nor VOID (see
-- ClaimRepository.refix). Existing claims (null) are worked out when read, as before, until next fixed.
ALTER TABLE claim ADD COLUMN due_by DATE;
ALTER TABLE hist.claim ADD COLUMN due_by DATE;
ALTER TABLE asof.claim ADD COLUMN due_by DATE;
== V51__settle_batch.sql
-- A bulk settle that settles at least one claim (one left PENDING counts) is a batch, numbered 1, 2, ... on the sheet
-- in the order the batches happen: the sheet keeps its last batch number (0: none yet), and each claim settled by one
-- keeps its number (null: not settled by a ba

file.content:
== V1__sheet.sql
-- A sheet: everything else in the app is kept per sheet. A row is created the first time its id
-- is loaded, so a sheet that was never loaded before starts empty.
CREATE TABLE sheet (
    id         VARCHAR(200) PRIMARY KEY,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
== V2__sheet_today.sql
-- The sheet's own "today": every date decision and default date in the app uses it, never the real
-- clock. A sheet starts on the real date of the day it was first loaded.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- The people on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on its sheet, ignoring case and surrounding spaces (names are stored
-- trimmed; the app refuses a duplicate with a message, this index is the backstop).
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name)));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims: an amount (two decimals, 0.00 or more), a date and a note (may be empty).
-- Listed newest first (by id, descending).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, person_id, id);
== V6__rate.sql
-- The sheet's rate for each grade: a percent with two decimals (0.00 to 100.00). A grade without
-- a row has no rate, so its claims' due shows n/a.
CREATE TABLE rate (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL,
    rate     DECIMAL(5, 2) NOT NULL CHECK (rate >= 0 AND rate <= 100),
    PRIMARY KEY (sheet_id, grade)
);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT';
== V8__claim_number.sql
-- A claim's number: given when it is opened, the sheet's next one (1, 2, ...), never reused.
-- A draft has none, and voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN claim_number INT;
== V9__claim_settled_due.sql
-- A claim's due fixed when it is settled: its amount times its person's grade's rate at that
-- moment, rounded half up to two decimals. Null while it is not settled, or when the grade had no
-- rate then (its due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
== V10__rate_from.sql
-- A rate can carry a from-date: a grade may have several rates, and a claim uses the one whose
-- from-date is the latest on or before the claim's date. A rate without one (null) applies from
-- the beginning of time. A grade has at most one rate per from-date (null included); setting it
-- again replaces it.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate DROP PRIMARY KEY;
== V11__claim_opened_by.sql
-- The signed-in user who opened a claim; null while it was never opened. That user cannot settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(200);
== V12__person_version.sql
-- How many times a person has been saved; an edit names the version it loaded and is refused when
-- someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V13__statement.sql
-- A person's statements: each records the person's due-total when it was taken (null when it was
-- n/a) and the sheet's today then. The latest (highest id) is the person's last statement.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(14, 2),
    taken_on  DATE           NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement: it shows and totals stated_due (null: n/a) instead
-- of its live figure, until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
== V14__period.sql
-- The sheet's periods: a name, unique on the sheet ignoring case and surrounding spaces (the app
-- refuses a duplicate with a message, the index is the backstop), and a from and to date, both
-- inclusive. No two periods on a sheet overlap; a claim belongs to the period containing its date.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name))),
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
== V15__period_closed.sql
-- A period can be closed. Closing fixes its due-total at that moment (later rate changes do not
-- alter it); no claim dated inside a closed period can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
== V16__person_retired.sql
-- A person can be retired from a date. A person with a retirement date set counts as retired at once,
-- whatever the date; no claim dated after it can be added (or edited to such a date).
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no live total;
-- their SETTLED claims still do.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
== V18__role_and_setting.sql
-- Each sheet assigns a role to a user name: clerk or steward. A name without a row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);

-- Each sheet's settings, by key. A null value is blank (for clerk-limit: no limit). A key without a row is blank.
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(50)  NOT NULL,
    setting_value VARCHAR(200),
    PRIMARY KEY (sheet_id, setting_key)
);
== V19__person_patron.sql
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id),
    patron_id BIGINT NOT NULL REFERENCES person (id),
    PRIMARY KEY (person_id, patron_id)
);
== V20__person_grade.sql
-- A person's grade is dated: each grade they are given applies from its from-date, the first one
-- (null) from the beginning of time. On a date, the grade in force is the one with the latest
-- from-date on or before it. A person has at most one grade per from-date; giving one again on the
-- same date replaces it.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL,
    from_date DATE
);
CREATE INDEX person_grade_person ON person_grade (person_id, from_date);
INSERT INTO person_grade (person_id, grade, from_date) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
== V21__claim_correction.sql
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the same
-- person that it corrects (null for any other claim). The amount may now be below 0.00, so the
-- column is rebuilt without its old CHECK (amount >= 0).
ALTER TABLE claim ADD COLUMN signed_amount DECIMAL(14, 2);
UPDATE claim SET signed_amount = amount;
ALTER TABLE claim ALTER COLUMN signed_amount SET NOT NULL;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN signed_amount RENAME TO amount;
ALTER TABLE claim ADD COLUMN corrects INT;
== V22__period_numbering.sql
-- A claim's number is now text: a sheet-wide number (1, 2, ...) or, while the sheet numbers by period, a number
-- within its period (<period name>-<n>, or X-<n> for a claim in no period). A correction names its claim the same way.
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);

-- Each sheet's per-period sequences, by key (a period's id, or X for claims in no period): the last number given.
CREATE TABLE claim_sequence (
    sheet_id    VARCHAR(200) NOT NULL REFERENCES sheet (id),
    seq_key     VARCHAR(50)  NOT NULL,
    last_number INT          NOT NULL DEFAULT 0,
    PRIMARY KEY (sheet_id, seq_key)
);
== V23__claim_listed.sql
-- Where a claim is listed: claims are listed newest first by this key, not by id, so a claim moved to
-- another person is listed as that person's newest. A claim takes the sheet's next key when it is
-- added or moved; the sheet keeps the last key it gave.
ALTER TABLE sheet ADD COLUMN last_claim_listed BIGINT NOT NULL DEFAULT 0;
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
UPDATE sheet SET last_claim_listed = COALESCE((SELECT MAX(c.id) FROM claim c WHERE c.sheet_id = sheet.id), 0);
CREATE INDEX claim_listed ON claim (sheet_id, person_id, listed);
== V24__claim_due_by.sql
-- A claim's due-by is fixed when it is added: its date plus the terms of its person's grade in force on that date
-- (the grade's own terms, setting terms-<grade>, else the sheet's terms). Later changes to the terms or to the claim's
-- date leave it as it is. Existing claims take their date plus the sheet's terms (14 until they are set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.setting_value AS INT) FROM sheet_setting s
    WHERE s.sheet_id = claim.sheet_id AND s.setting_key = 'terms'), 14), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V25__claim_log.sql
-- A claim's status log: one line per status it has had, in the order it had them (by id) — who made the change, the
-- sheet's today then, and the claim's due as computed at that moment (null: n/a). Its DRAFT line is written when it is added.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(10)    NOT NULL,
    by_user   VARCHAR(200)   NOT NULL,
    logged_on DATE           NOT NULL,
    due       DECIMAL(14, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
== V26__person_hold.sql
-- A person may have several holds over time, each from its from-date to its to-date (null: open-ended), both
-- inclusive. A hold leaves out of the live totals only the person's OPEN and PENDING claims dated within it that no
-- statement binds. A person held before keeps a hold from the beginning of time (null from-date).
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id, id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, NULL, NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V27__rate_to.sql
-- A rate can carry a to-date: it applies through that date (null: with no end). A claim dated after
-- the to-date of the rate that would apply to it, with no later rate in force then, has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
== V28__period_person_total.sql
-- Closing a period also fixes each person's due-total for it, for every person on the sheet at that moment
-- (a person added later has none: 0.00). The period's closed_total is the sum of these. Reopening removes them.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V29__setting_from.sql
-- The settings that carry a figure (the floor, the late percent, the terms and each grade's, the clerk limit, the cap)
-- are dated: each value is in force from its from-date until the next one's. A null value is blank. A value already
-- set before settings were dated is kept as in force from the beginning of time.
CREATE TABLE sheet_setting_from (
    sheet_id      VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(50)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(200),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);

INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)
SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM sheet_setting
WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');

DELETE FROM sheet_setting WHERE setting_key NOT IN ('policy-date', 'period-numbering-from');
== V30__claim_deferred.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches that date it counts
-- in no total, is not overdue, cannot be settled and is left unbound by a statement (null: never deferred).
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V31__claim_proofs.sql
-- How many proofs a claim carries: raised by one at a time while it is neither SETTLED nor VOID. A claim whose due is
-- above the proof threshold in force on its date cannot be settled or approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT DEFAULT 0 NOT NULL;
== V32__role_viewer.sql
-- A third role, viewer: sees every screen and figure and may change nothing. The role's check is
-- unnamed (generated), so the table is rebuilt with the wider check.
CREATE TABLE sheet_role_new (
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_new (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
== V33__claim_split_from.sql
-- The number of the claim an OPEN claim was split off (null: not split off one). The claim split keeps the rest of its
-- amount and shows nothing.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(50);
== V34__person_watch.sql
-- The users watching each person, in the order they started watching (id order). A user watches a person at most once.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
== V35__delegation.sql
-- A steward's delegation of the steward role to a user name, for a from-date to a to-date (inclusive) by the sheet's
-- today. While the sheet's today is inside the range the user acts as a steward, for the steward who delegated.
CREATE TABLE sheet_delegation (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    by_user   VARCHAR(200) NOT NULL
);
CREATE INDEX sheet_delegation_user ON sheet_delegation (sheet_id, user_name);
== V36__sheet_archived.sql
-- An archived sheet: everything on it stays visible, and every change to it is refused.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN DEFAULT FALSE NOT NULL;
== V37__person_terms.sql
-- A person's own terms: a whole number of days, null for none. A claim added for the person is due by
-- its date plus these terms, else their grade's, else the sheet's.
ALTER TABLE person ADD COLUMN terms INT;
== V38__claim_lock.sql
-- A claim's editor lock: the signed-in user whose open editor holds the claim. Others cannot open its
-- editor or save it until the holder saves or cancels, or the sheet's today changes (every lock is dropped).
CREATE TABLE claim_lock (
    claim_id  BIGINT       PRIMARY KEY REFERENCES claim (id),
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    locked_by VARCHAR(200) NOT NULL
);
CREATE INDEX claim_lock_sheet ON claim_lock (sheet_id);
== V39__period_soft_close.sql
-- A period can be soft-closed: its due-total (closed_total) and each person's (period_person_total) are fixed as
-- closing fixes them, but claims dated inside it can still be added, edited, opened, settled and voided. A
-- soft-closed period is not closed; closing it fixes the figures afresh, reopening removes them.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period containing its date was soft-closed is a late entry, for good.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
== V40__sheet_snapshot.sql
-- A sheet as it stood at the end of a run of its todays: taken as the sheet's today moves on from `through` to
-- `until`, it holds every change made while the sheet's today was `through` or earlier, and none made later. A
-- statement as of a date reads the latest snapshot with through <= date < until (see SheetHistory).
CREATE TABLE sheet_snapshot (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    through  DATE         NOT NULL,
    until    DATE         NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, id);

-- The snapshotted rows: each table a statement's figures read, with the snapshot's id last.
CREATE SCHEMA hist;
CREATE TABLE hist.sheet AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet t WHERE FALSE;
CREATE TABLE hist.person AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person t WHERE FALSE;
CREATE TABLE hist.person_grade AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_grade t WHERE FALSE;
CREATE TABLE hist.person_hold AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_hold t WHERE FALSE;
CREATE TABLE hist.person_patron AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_patron t WHERE FALSE;
CREATE TABLE hist.statement AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM statement t WHERE FALSE;
CREATE TABLE hist.claim AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim t WHERE FALSE;
CREATE TABLE hist.rate AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM rate t WHERE FALSE;
CREATE TABLE hist.sheet_setting AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_setting t WHERE FALSE;
CREATE TABLE hist.sheet_setting_from AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM sheet_setting_from t WHERE FALSE;
CREATE INDEX hist_sheet_snapshot ON hist.sheet (snapshot_id);
CREATE INDEX hist_person_snapshot ON hist.person (snapshot_id);
CREATE INDEX hist_person_grade_snapshot ON hist.person_grade (snapshot_id);
CREATE INDEX hist_person_hold_snapshot ON hist.person_hold (snapshot_id);
CREATE INDEX hist_person_patron_snapshot ON hist.person_patron (snapshot_id);
CREATE INDEX hist_statement_snapshot ON hist.statement (snapshot_id);
CREATE INDEX hist_claim_snapshot ON hist.claim (snapshot_id);
CREATE INDEX hist_rate_snapshot ON hist.rate (snapshot_id);
CREATE INDEX hist_sheet_setting_snapshot ON hist.sheet_setting (snapshot_id);
CREATE INDEX hist_sheet_setting_from_snapshot ON hist.sheet_setting_from (snapshot_id);

-- A snapshot laid out as the live tables, for the length of one request: the repositories read it unchanged with
-- this schema current, the sheet's today standing at the statement's date. Emptied again before the request ends.
CREATE SCHEMA asof;
CREATE TABLE asof.sheet AS SELECT * FROM sheet WHERE FALSE;
CREATE TABLE asof.person AS SELECT * FROM person WHERE FALSE;
CREATE TABLE asof.person_grade AS SELECT * FROM person_grade WHERE FALSE;
CREATE TABLE asof.person_hold AS SELECT * FROM person_hold WHERE FALSE;
CREATE TABLE asof.person_patron AS SELECT * FROM person_patron WHERE FALSE;
CREATE TABLE asof.statement AS SELECT * FROM statement WHERE FALSE;
CREATE TABLE asof.claim AS SELECT * FROM claim WHERE FALSE;
CREATE TABLE asof.rate AS SELECT * FROM rate WHERE FALSE;
CREATE TABLE asof.sheet_setting AS SELECT * FROM sheet_setting WHERE FALSE;
CREATE TABLE asof.sheet_setting_from AS SELECT * FROM sheet_setting_from WHERE FALSE;
== V41__sheet_snapshot_whole.sql
-- The as-of view: the whole screen is shown as the sheet stood at the end of a date, so a snapshot (see V40) holds
-- every table the screen reads, not only those a statement's figures read.
CREATE TABLE hist.person_watch AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_watch t WHERE FALSE;
CREATE TABLE hist.claim_log AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_log t WHERE FALSE;
CREATE TABLE hist.claim_lock AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_lock t WHERE FALSE;
