ALTER TABLE claim ADD COLUMN edited_by VARCHAR(200);
ALTER TABLE hist.claim ADD COLUMN edited_by VARCHAR(200);
ALTER TABLE asof.claim ADD COLUMN edited_by VARCHAR(200);
== V50__claim_due_by_fixed.sql
-- A claim's due-by is fixed again when it is added (counted over the sheet's holidays as they stand then), and is
-- re-fixed only when a holiday is added on or before it while the claim is neither SETTLED nor VOID (see
-- ClaimRepository.refix). Existing claims (null) are worked out when read, as before, until next fixed.
ALTER TABLE claim ADD COLUMN due_by DATE;
ALTER TABLE hist.claim ADD COLUMN due_by DATE;
ALTER TABLE asof.claim ADD COLUMN due_by DATE;
== V51__settle_batch.sql
-- A bulk settle that settles at least one claim (one left PENDING counts) is a batch, numbered 1, 2, ... on the sheet
-- in the order the batches happen: the sheet keeps its last batch number (0: none yet), and each claim settled by one
-- keeps its number (null: not settled by a batch).
ALTER TABLE sheet ADD COLUMN last_settle_batch INT NOT NULL DEFAULT 0;
ALTER TABLE hist.sheet ADD COLUMN last_settle_batch INT;
ALTER TABLE asof.sheet ADD COLUMN last_settle_batch INT;
ALTER TABLE claim ADD COLUMN settle_batch INT;
ALTER TABLE hist.claim ADD COLUMN settle_batch INT;
ALTER TABLE asof.claim ADD COLUMN settle_batch INT;
== V52__person_contact.sql
-- A person's contact: trimmed and lower-cased, null for none. No two people on a sheet share one.
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
-- The sheet's snapshots, and their layout as of a date, carry it too.
ALTER TABLE hist.person ADD COLUMN contact VARCHAR(255);
ALTER TABLE asof.person ADD COLUMN contact VARCHAR(255);
== V53__person_alias.sql
-- A person's aliases: other names they go by, stored trimmed. An alias shares the names' uniqueness on its sheet,
-- ignoring case and surrounding spaces: no alias equals any name or other alias there (the app refuses one with a
-- message; this index is the backstop against another alias).
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(alias)))
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.person_alias AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_alias t WHERE FALSE;
CREATE INDEX hist_person_alias_snapshot ON hist.person_alias (snapshot_id);
CREATE TABLE asof.person_alias AS SELECT * FROM person_alias WHERE FALSE;
== V54__claim_template.sql
-- The sheet's claim templates: a name (stored trimmed, at most once on its sheet: saving a name again replaces that
-- template), an amount the claim form would accept and a note. A claim made from one copies its amount and note then.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL,
    note     VARCHAR(1000)  NOT NULL
);
CREATE UNIQUE INDEX claim_template_sheet_name ON claim_template (sheet_id, name);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.claim_template AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM claim_template t WHERE FALSE;
CREATE INDEX hist_claim_template_snapshot ON hist.claim_template (snapshot_id);
CREATE TABLE asof.claim_template AS SELECT * FROM claim_template WHERE FALSE;
== V55__pool.sql
-- The sheet's pools: a name (stored trimmed, at most once on its sheet: the app refuses a repeat with a message, the
-- index is the backstop) and its members, each a person of the sheet at most once in the pool with a share percent
-- (two decimals, more than 0.00 and at most 100.00). A person can be in several pools.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.pool AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM pool t WHERE FALSE;
CREATE INDEX hist_pool_snapshot ON hist.pool (snapshot_id);
CREATE TABLE asof.pool AS SELECT * FROM pool WHERE FALSE;
CREATE TABLE hist.pool_member AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM pool_member t WHERE FALSE;
CREATE INDEX hist_pool_member_snapshot ON hist.pool_member (snapshot_id);
CREATE TABLE asof.pool_member AS SELECT * FROM pool_member WHERE FALSE;
== V56__person_patron_named.sql
-- The order a person's patrons were named in: each row's place in one sheet-wide sequence (existing rows take it in
-- the order they are read). A person's patrons share 100.00 by it (see Person.getPatronShares).
CREATE SEQUENCE person_patron_named;
ALTER TABLE person_patron ADD COLUMN named BIGINT DEFAULT NEXT VALUE FOR person_patron_named NOT NULL;
-- The sheet's snapshots, and their layout as of a date, carry it too.
ALTER TABLE hist.person_patron ADD COLUMN named BIGINT;
ALTER TABLE asof.person_patron ADD COLUMN named BIGINT;
== V57__pool_member_pool.sql
-- A pool member may be another pool of the sheet instead of a person: exactly one of person_id and member_pool_id is
-- set. A pool is a member of at most one pool, never of itself through any chain, and a chain of pools is at most
-- three deep (the app refuses each with a message). A member pool has no pot of its own: its pot is its cut in the
-- pool above.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);
-- The sheet's snapshots, and their layout as of a date, carry it too.
ALTER TABLE hist.pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE hist.pool_member ADD COLUMN member_pool_id BIGINT;
ALTER TABLE asof.pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE asof.pool_member ADD COLUMN member_pool_id BIGINT;
== V58__person_position.sql
-- A person's place in the sheet's list: the list, the rollup lines and every action that works in list order go by
-- it (lowest first). New people go to the end; existing people keep the order they were added in.
ALTER TABLE person ADD COLUMN list_position BIGINT;
UPDATE person SET list_position = id;
ALTER TABLE person ALTER COLUMN list_position SET NOT NULL;
-- The sheet's snapshots, and their layout as of a date, carry it too.
ALTER TABLE hist.person ADD COLUMN list_position BIGINT;
UPDATE hist.person SET list_position = id;
ALTER TABLE asof.person ADD COLUMN list_position BIGINT;
== V59__person_origin.sql
-- The sheet a transferred person came from; null for anyone not transferred in.
ALTER TABLE person ADD COLUMN origin VARCHAR(255);
-- The sheet's snapshots, and their layout as of a date, carry it too.
ALTER TABLE hist.person ADD COLUMN origin VARCHAR(255);
ALTER TABLE asof.person ADD COLUMN origin VARCHAR(255);
== V60__pool_member_dates.sql
-- A pool membership may carry a from-date and a to-date (either optional; the app refuses a to-date before the
-- from-date). A member whose dates do not include the sheet's today is left out of the pool entirely: not in its total
-- share, not in its balance, and no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
-- The sheet's snapshots, and their layout as of a date, carry them too.
ALTER TABLE hist.pool_member ADD COLUMN from_date DATE;
ALTER TABLE hist.pool_member ADD COLUMN to_date DATE;
ALTER TABLE asof.pool_member ADD COLUMN from_date DATE;
ALTER TABLE asof.pool_member ADD COLUMN to_date DATE;
== V61__person_retirement.sql
-- A retired person can be unretired: their retirement is then kept as a past one, from its from-date to the day they
-- were unretired, and they are no longer retired (retired_from cleared). No claim dated strictly between a past
-- retirement's from-date and to-date can be added (or edited to such a date).
CREATE TABLE person_retirement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE   NOT NULL
);
CREATE INDEX person_retirement_person ON person_retirement (person_id, id);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.person_retirement AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM person_retirement t WHERE FALSE;
CREATE INDEX hist_person_retirement_snapshot ON hist.person_retirement (snapshot_id);
CREATE TABLE asof.person_retirement AS SELECT * FROM person_retirement WHERE FALSE;

