# OfficeFloor REST wiring

Domain REST endpoints are declared here as OfficeFloor YAML, served by the
`officefloor-rest-spring-boot-4-starter` inside the Spring Boot host. Put them under `rest/api/` so
their paths start with `/api/` — `SpaConfig` only lets `/api/*` reach the backend; a non-`/api/`
path returns the SPA's `index.html` instead of your endpoint. Directory nesting maps to path
segments, so `rest/api/owners.GET.yml` → `GET /api/owners`. Each route is its own file:

```
# officefloor/rest/api/<path>.GET.yml   (or .POST.yml, {param}.GET.yml, ...)
service:
  class: net.officefloor.hq.app.<SomeLogic>   # a class with a service(...) method
```

The logic class's `service(...)` method takes injected dependencies (Spring `@Service` beans, the
data layer) and a `net.officefloor.web.ObjectResponse<T>` to send the response.

(The `/actuator/health` readiness endpoint is Spring-side — Actuator — not an OfficeFloor route.)
# A steward archives the sheet: everything stays visible, every change after is refused. Anyone else, or a sheet
# already archived, is refused and nothing is written.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: by
by:
  class: net.officefloor.hq.app.sheet.ValidateArchive
  next: ensure
ensure:
  class: net.officefloor.hq.app.sheet.EnsureSheet
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplyArchive
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.sheet.RecordSheetArchived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheetToday
  govern: [ transaction ]
# Load a sheet by id: an id never used before starts an empty sheet.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: ensure
ensure:
  class: net.officefloor.hq.app.sheet.EnsureSheet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
# Transfer a person to another sheet by id. Validate the body before touching the store, so a refusal writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.ValidateTransfer
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: rollup-before
rollup-before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonTransferred
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: audit-to
audit-to:
  class: net.officefloor.hq.app.person.RecordPersonArrived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The user archiving the sheet. */
public class ValidateArchive {
    public void validate(@RequestBody ArchiveRequest request, Out<ChangedBy> changedBy) throws BadRequestException {
        changedBy.set(ChangedBy.of(request == null ? null : request.by()));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/** Archives the sheet: only a steward may, and a sheet already archived is refused like any other change. */
public class ApplyArchive {
    public void apply(@Val SheetResponse sheet, @Val ChangedBy by, RoleRepository roles, SheetRepository sheets)
            throws BadRequestException {
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), by.name()))) {
            throw new BadRequestException("Only a steward may archive the sheet");
        }
        sheets.refuseArchived(sheet.id());
        sheets.archive(sheet.id());
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordSheetArchived {
    public void record(@Val SheetResponse sheet, @Val ChangedBy by, Audit audit) {
        audit.record("SHEET_ARCHIVED sheet=" + sheet.id() + " by=" + by.name());
    }
}
package net.officefloor.hq.app.sheet;

/** Archive the sheet, by the signed-in user (`by`). */
public record ArchiveRequest(String by) {
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;

public class EnsureSheet {
    public void ensure(@Val SheetResponse sheet, SheetRepository repository) {
        repository.ensure(sheet.id());
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class ValidateSheetId {
    public void validate(@PathVariable("sheetId") String sheetId, Out<SheetResponse> sheet)
            throws BadRequestException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (id.isEmpty() || id.length() > 200) {
            throw new BadRequestException("Enter a sheet id");
        }
        sheet.set(new SheetResponse(id));
    }
}

